import{_ as e,o as l,c as s,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"CDS Hammer (Day 1) - OSD: Opportunistic Whole-Object Checksums","description":"","frontmatter":{"title":"CDS Hammer (Day 1) - OSD: Opportunistic Whole-Object Checksums","date":"2014-10-29T00:00:00.000Z","updated":"2014-10-29T00:00:00.000Z","tags":["Ceph","distributed storage","checksums","OSD","object storage","storage reliability"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_Hammer_Day_1_-_OSD_-_Opportunistic_Whole-Object_Checksums.md","filePath":"posts/2014/CDS_Hammer_Day_1_-_OSD_-_Opportunistic_Whole-Object_Checksums.md","lastUpdated":1780459816000}'),r={name:"posts/2014/CDS_Hammer_Day_1_-_OSD_-_Opportunistic_Whole-Object_Checksums.md"};function o(a,t,p,_,n,u){return l(),s("div",null,[...t[0]||(t[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： 在 Ceph 存储系统中引入机会主义全对象校验和</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Marcel、Sam、Sage、Heather、David、Craig 等</p><p><strong>会议内容</strong>：</p><p><strong>1. 会议背景</strong></p><ul><li>Ceph 存储系统中，对存储在磁盘上的数据进行校验和计算较为昂贵，因此通常不进行校验。</li><li>现有的机会主义校验和机制仅对块级别进行校验，且仅在读取或覆盖完整块时更新和验证。</li><li>本次会议讨论了在 Ceph 中引入机会主义全对象校验和的方案。</li></ul><p><strong>2. 方案概述</strong></p><ul><li>该方案的核心思想是在进行数据清理（scrub）时，记录每个对象的完整校验和，并将其存储在对象信息（object info）结构中。</li><li>当后续读取对象时，将计算出的校验和与存储的校验和进行比较，若不一致则触发错误，并记录相关信息以便后续修复。</li></ul><p><strong>3. 讨论要点</strong></p><ul><li><strong>校验和类型</strong>： <ul><li>讨论了使用 CRC32、CRC32C 或 SHA 等校验和算法。</li><li>决定使用 CRC32，因其计算速度快，对随机位翻转的检测能力较强。</li></ul></li><li><strong>校验和存储位置</strong>： <ul><li>讨论了将校验和存储在对象信息结构中还是作为单独的属性。</li><li>决定将校验和存储在对象信息结构中，以便于后续修改和扩展。</li></ul></li><li><strong>校验和更新时机</strong>： <ul><li>讨论了在校验和更新过程中，如何处理对象的修改和损坏。</li><li>认为只有当所有副本都保持一致时，才进行校验和更新，以降低风险。</li></ul></li><li><strong>与现有功能的兼容性</strong>： <ul><li>认为该方案与现有功能（如 scrub、repair）兼容，且不会对性能产生显著影响。</li></ul></li></ul><p><strong>4. 行动计划</strong></p><ul><li>完善方案设计，并确定具体实现细节。</li><li>在 Ceph 中实现机会主义全对象校验和功能。</li><li>对现有功能进行测试和验证。</li></ul><p><strong>5. 其他事项</strong></p><ul><li>讨论了是否引入更通用的校验和表示方式，以方便后续扩展。</li><li>认为目前使用 CRC32 已能满足需求，且引入通用表示方式会增加复杂度。</li></ul><p><strong>总结</strong>：</p><p>本次会议讨论了在 Ceph 中引入机会主义全对象校验和的方案，并确定了具体实现细节。该方案有助于提高 Ceph 存储系统的可靠性和可维护性。</p>',17)])])}const C=e(r,[["render",o]]);export{g as __pageData,C as default};
